import Foundation

/// Which pasteboard changes go into history. Pure: the watcher passes in
/// what it saw.
enum ClipboardPolicy {
    /// nspasteboard.org markers. Password managers flag secrets as concealed;
    /// transient and auto-generated content is by convention not for history.
    static let concealed = "org.nspasteboard.ConcealedType"
    static let neverRecorded: Set<String> = ["org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType"]

    static func shouldRecord(types: [String], sourceApp: String?, ignoreConcealed: Bool, ignoredApps: Set<String>) -> Bool {
        if let sourceApp, ignoredApps.contains(sourceApp) { return false }
        if types.contains(where: neverRecorded.contains) { return false }
        if ignoreConcealed && types.contains(concealed) { return false }
        return true
    }
}

/// When the watcher next looks at the pasteboard's change counter.
///
/// Copies follow input: a key press or a click. So the counter is read for a
/// few seconds after each one and not at all while the keyboard and mouse are
/// quiet — an idle Mac is never woken for the clipboard.
enum PollSchedule {
    /// Delay before the first look after input resumes.
    static let first: TimeInterval = 0.25

    /// The delay to the next look, or nil to stop until the next input.
    /// `hasInputSignal` is false when flit cannot see key presses (no
    /// Accessibility grant, or a password field holding the keyboard). It
    /// then cannot be told when to resume, so it slows down instead of stopping.
    static func next(quietFor quiet: TimeInterval, hasInputSignal: Bool) -> TimeInterval? {
        if quiet < 1.5 { return 0.5 }
        if quiet < 8 { return 2 }
        return hasInputSignal ? nil : 3
    }
}

/// One line in the clipboard panel.
enum ClipRow: Identifiable, Equatable {
    case snippet(Snippet)
    case entry(ClipEntry)

    enum Mode { case history, snippets }

    var id: String {
        switch self {
        case .snippet(let s): return "s\(s.id)"
        case .entry(let e): return "e\(e.id)"
        }
    }

    /// History with no query is just the copies, newest first, so the hotkey
    /// followed by Return pastes the latest one. A search also brings in
    /// matching snippets, ahead of the copies. Snippets mode lists snippets only.
    static func build(store: ClipboardStore, mode: Mode, query: String, limit: Int = 200) -> [ClipRow] {
        let searching = !query.trimmingCharacters(in: .whitespaces).isEmpty
        switch mode {
        case .snippets:
            return store.snippets(matching: query).map(ClipRow.snippet)
        case .history:
            let snippets = searching ? store.snippets(matching: query).map(ClipRow.snippet) : []
            return snippets + store.entries(matching: query, limit: limit).map(ClipRow.entry)
        }
    }
}
